mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.2) * p.xz;
  vec3 q = abs(p) - vec3(0.42, 1.85, 0.42);
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0) - 0.09;
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.2, -3.8);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 8.0) break;
    t += d * 0.8;
  }
  vec3 sunGlow = vec3(0.35, 0.65, 1.25) * (1.0 / (1.0 + length(p - vec2(0.8, 0.8)) * 2.8));
  vec3 col = vec3(0.02, 0.03, 0.08) + sunGlow;
  if (t < 8.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(map(pos+e.xyy)-map(pos-e.xyy), map(pos+e.yxy)-map(pos-e.yxy), map(pos+e.yyx)-map(pos-e.yyx)));
    vec3 l = normalize(vec3(1.5, 1.5, -2.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 48.0);
    col = vec3(0.65, 0.75, 0.95) * 0.4 + diff * vec3(0.5, 0.85, 1.2) + spec * vec3(1.25);
  }
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
